import { describe, expect, it } from 'vitest';
import { capSnapshot, MAX_SNAPSHOT_BYTES, MAX_SNAPSHOT_ITEMS } from './snapshotCache';

/**
 * Snapshot cap / eviction — failing-first unit tests for
 * [TOG-25326](/TOG/issues/TOG-25326) (slice S8: stale list fallback).
 *
 * Builder: implement `./snapshotCache` (sibling module, same directory) on
 * THIS branch and do NOT edit this file. Required surface (the smallest
 * thing that satisfies "capped count + bytes, eviction noted"):
 *
 *   export const MAX_SNAPSHOT_ITEMS: number;  // max tracks kept (>= 1)
 *   export const MAX_SNAPSHOT_BYTES: number;  // max JSON bytes kept (>= 1024)
 *   export function capSnapshot<T>(items: T[], nowIso?: string):
 *     { items: T[]; updatedAt: string; evicted: number };
 *
 * Semantics pinned below: input order is newest-first; the result keeps a
 * prefix of the input (never reorders, never merges across calls — a fresh
 * success replaces the snapshot); `evicted` counts the dropped tail so the
 * bound is observable, not just a code comment; byte size is measured with
 * `JSON.stringify(items).length`; `updatedAt` echoes the passed `nowIso` or
 * defaults to now.
 *
 * RED before the build (`./snapshotCache` does not exist); GREEN after.
 */

interface SeedItem {
	id: string;
	title: string;
	artist: string;
	pad?: string;
}

function track(n: number, pad = ''): SeedItem {
	return { id: `track-${n}`, title: `Track ${n}`, artist: `Artist ${n}`, pad };
}

describe('snapshot caps', () => {
	it('are sane finite bounds that can hold at least one track', () => {
		expect(Number.isInteger(MAX_SNAPSHOT_ITEMS)).toBe(true);
		expect(MAX_SNAPSHOT_ITEMS).toBeGreaterThanOrEqual(1);
		expect(Number.isFinite(MAX_SNAPSHOT_BYTES)).toBe(true);
		expect(MAX_SNAPSHOT_BYTES).toBeGreaterThanOrEqual(1024);
	});

	it('passes a small fresh list through untouched with zero evictions', () => {
		const now = '2026-10-15T20:00:00.000Z';
		const result = capSnapshot([track(1), track(2)], now);

		expect(result.items.map((t) => t.id)).toEqual(['track-1', 'track-2']);
		expect(result.evicted).toBe(0);
		expect(result.updatedAt).toBe(now);
	});

	it('caps the track count, keeping the newest prefix and noting evictions', () => {
		const input = Array.from({ length: MAX_SNAPSHOT_ITEMS + 5 }, (_, i) => track(i));
		const result = capSnapshot(input, '2026-10-15T20:00:00.000Z');

		expect(result.items.length).toBe(MAX_SNAPSHOT_ITEMS);
		expect(result.items.map((t) => t.id)).toEqual(input.slice(0, MAX_SNAPSHOT_ITEMS).map((t) => t.id));
		expect(result.evicted).toBe(5);
		expect(result.evicted).toBe(input.length - result.items.length);
	});

	it('caps JSON bytes, keeping a prefix that fits and noting evictions', () => {
		const count = Math.min(8, Math.max(2, MAX_SNAPSHOT_ITEMS));
		// Every item oversized so the whole list cannot fit, but the first
		// item alone fits (caps floor ≥ 1024, see the sanity test above).
		const pad = 'x'.repeat(Math.ceil(MAX_SNAPSHOT_BYTES / count) + 100);
		const input = Array.from({ length: count }, (_, i) => track(i, pad));
		expect(JSON.stringify(input).length).toBeGreaterThan(MAX_SNAPSHOT_BYTES);

		const result = capSnapshot(input, '2026-10-15T20:00:00.000Z');

		expect(JSON.stringify(result.items).length).toBeLessThanOrEqual(MAX_SNAPSHOT_BYTES);
		expect(result.items.length).toBeGreaterThan(0);
		expect(result.items.length).toBeLessThan(input.length);
		expect(result.items.map((t) => t.id)).toEqual(
			input.slice(0, result.items.length).map((t) => t.id)
		);
		expect(result.evicted).toBe(input.length - result.items.length);
	});

	it('replaces rather than merges: a fresh list contains only the fresh ids', () => {
		const first = capSnapshot([track(1), track(2)], '2026-10-15T20:00:00.000Z');
		expect(first.items.map((t) => t.id)).toEqual(['track-1', 'track-2']);

		const second = capSnapshot([track(9)], '2026-10-15T21:00:00.000Z');
		expect(second.items.map((t) => t.id)).toEqual(['track-9']);
		expect(second.updatedAt).toBe('2026-10-15T21:00:00.000Z');
	});

	it('stamps now when no timestamp is passed', () => {
		const before = Date.now();
		const result = capSnapshot([track(1)]);
		const after = Date.now();

		const stamped = Date.parse(result.updatedAt);
		expect(Number.isNaN(stamped)).toBe(false);
		expect(stamped).toBeGreaterThanOrEqual(before - 1000);
		expect(stamped).toBeLessThanOrEqual(after + 1000);
	});

	it('caps an empty list to an empty snapshot with zero evictions', () => {
		const result = capSnapshot([], '2026-10-15T20:00:00.000Z');

		expect(result.items).toEqual([]);
		expect(result.evicted).toBe(0);
		expect(result.updatedAt).toBe('2026-10-15T20:00:00.000Z');
	});
});
